  componentDidMount() {
    // One clock for everything that moves on its own: the New Year countdown and the Easter bunny
    this.timer = setInterval(() => {
      const st = this.state;
      const next = { tick: st.tick + 1 };
      if (st.mid && st.mid.n > 0) next.mid = { n: st.mid.n - 1 };
      else if (st.mid && st.mid.n === 0) next.mid = { boom: true, at: st.tick };
      else if (st.mid && st.mid.boom && st.tick - st.mid.at > 9) next.mid = { done: true };
      if (st.theme === 'easter' && st.tick % 3 === 0) {
        const x = 8 + Math.random() * 78;
        next.bunny = { x, face: x > st.bunny.x ? 1 : -1 };
      }
      this.setState(next);
    }, 1000);
  }
  componentWillUnmount() { clearInterval(this.timer); }

  // Each theme's settings live in opts[themeId]; anything not set falls back to DEFAULTS
  opt(id) {
    const d = this.DEFAULTS[id] || {}, o = this.state.opts[id] || {};
    const out = { ...d, ...o };
    for (const k of Object.keys(d)) if (d[k] && typeof d[k] === 'object' && !Array.isArray(d[k])) out[k] = { ...d[k], ...(o[k] || {}) };
    return out;
  }
  setOpt(id, key, val) { this.setState({ opts: { ...this.state.opts, [id]: { ...(this.state.opts[id] || {}), [key]: val } } }); }
  flipOpt(id, group, key) { const cur = this.opt(id)[group]; this.setOpt(id, group, { ...cur, [key]: cur[key] ? 0 : 1 }); }

