    add(z, { left: x, bottom: 4, w: 1, vb: [10, 60], noScale: true, cls: 'launch', delay, layers: [{ d: this.R(4, 0, 2, 60, 1), grad: [c, c], go: [1, 0], gv: true }, { d: this.C(5, 2, 4), fill: '#fff' }, { d: this.C(5, 2, 7), fill: c, op: .5 }] });
    add(z, { left: this.n1(x + .5 - w / 2), top: this.n1(19.4 - w * .8), w, vb: [100, 100], noScale: true, cls: 'pop3', delay, origin: '50% 50%', layers: this.fwLayers(c, 18) });
