      add('back', { left: 0, bottom: 0, w: 100, vb: [1000, 600], noScale: true, cls: 'beam', origin: '50% 100%', layers: [{ d: d1, stroke: c1, sw: 2.2, op: .45 + I * .45 }] });
      add('back', { left: 0, bottom: 0, w: 100, vb: [1000, 600], noScale: true, cls: 'beamwide', delay: '-1.3s', origin: '50% 100%', layers: [{ d: d2, stroke: c2, sw: 2.2, op: .45 + I * .45 }] });
