    if (fx.fog) add('front', { left: -10, bottom: -6, w: 120, vb: [1200, 200], noScale: true, cls: 'drift', layers: [{ d: this.E(300, 140, 360, 70) + this.E(800, 150, 420, 80), fill: '#fff', op: .09 + I * .06 }, { d: this.E(560, 170, 520, 60), fill: '#fff', op: .07 }] });
    if (fx.crowd) {
      // three groups of people in silhouette, each jumping on its own beat
      [0, 1, 2].forEach(g => {
        let d = '';
        for (let x = 10 + g * 9; x < 1000; x += 27) {
          const h = 58 + ((x * 7) % 14);
          d += this.C(x, 120 - h, 9) + `M${x - 15} 120C${x - 15} ${120 - h + 22} ${x + 15} ${120 - h + 22} ${x + 15} 120z`;
          if ((x + g) % 4 === 0) d += `M${x - 8} ${120 - h + 18}L${x - 18} ${120 - h - 14}L${x - 13} ${120 - h - 16}L${x - 4} ${120 - h + 16}zM${x + 8} ${120 - h + 18}L${x + 18} ${120 - h - 14}L${x + 13} ${120 - h - 16}L${x + 4} ${120 - h + 16}z`;
        }
        add('front', { left: 0, bottom: -2, w: 100, vb: [1000, 120], noScale: true, cls: 'jump', delay: -(g * .19).toFixed(2) + 's', layers: [{ d, fill: '#06060a', op: .92 }] });
      });
    }
    if (fx.cannons) [[2, -12, '0s'], [86, 12, '-2s']].forEach(([left, rot, delay]) => {
      add('front', { left: left + 3, bottom: 3, w: 5, vb: [50, 80], rot, layers: [{ d: 'M14 80L36 80 44 20 6 20z', fill: '#343a40' }, { d: this.E(25, 20, 19, 5), fill: '#495057' }] });
      add('front', { left: left - 2, bottom: 10, w: 16, vb: [160, 160], rot, cls: 'cannon', delay, origin: '50% 100%', layers: Array.from({ length: 22 }, (_, i) => ({ d: this.R(76 + Math.cos(i * 1.3) * 70, 100 - Math.abs(Math.sin(i * 1.9)) * 96, 8, 4, 1), fill: [c1, c2, '#fde047', '#fff'][i % 4], tf: `rotate(${i * 33} 80 80)` })) });
    });
