    for (let i = 0; i < 9; i++) tiles.push({ d: this.R(20 + (i * 23) % 60, 98 + (i * 17) % 62, 6, 6), fill: '#fff', cls: 'twinkle', delay: -(i * .33).toFixed(2) + 's' });
