    const cx = 130, cy = 120, r = 112, L = [];
    const leaf = (x, y, ang) => ({ d: 'M0 0C4 -6 4 -16 0 -22C-4 -16 -4 -6 0 0z', fill: outline ? 'none' : color, stroke: outline ? color : 'none', sw: outline ? 1 : 0, tf: `translate(${this.n1(x)} ${this.n1(y)}) rotate(${this.n1(ang)})` });
